type Position = {
  offset: number;
  line: number;
  column: number;
};

type TextNode = { type: "text"; value: string };
type ValueNode = {
  type: "value";
  path: string;
  escaped: boolean;
  position: Position;
};
type BlockNode = {
  type: "if" | "each";
  path: string;
  consequent: Node[];
  alternate: Node[];
  position: Position;
};
type Node = TextNode | ValueNode | BlockNode;

type OpenBlock = {
  node: BlockNode;
  parent: Node[];
  inElse: boolean;
};

type LoopFrame = { value: unknown; index: number };
type RenderContext = { root: unknown; loops: LoopFrame[] };

class TemplateError extends Error {
  constructor(message: string, position: Position) {
    super(`${message} at line ${position.line}, column ${position.column}`);
    this.name = "TemplateError";
  }
}

function positionAt(source: string, offset: number): Position {
  let line = 1;
  let column = 1;

  for (let index = 0; index < offset; index += 1) {
    if (source.charCodeAt(index) === 10) {
      line += 1;
      column = 1;
    } else {
      column += 1;
    }
  }

  return { offset, line, column };
}

function requirePath(path: string, position: Position, tag: string): string {
  if (path.length === 0) {
    throw new TemplateError(`Missing path in ${tag} tag`, position);
  }
  return path;
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  const stack: OpenBlock[] = [];
  let target = root;
  let cursor = 0;

  while (cursor < template.length) {
    const start = template.indexOf("{{", cursor);
    if (start === -1) {
      target.push({ type: "text", value: template.slice(cursor) });
      break;
    }

    if (start > cursor) {
      target.push({ type: "text", value: template.slice(cursor, start) });
    }

    const triple = template.startsWith("{{{", start);
    const close = triple ? "}}}" : "}}";
    const contentStart = start + (triple ? 3 : 2);
    const end = template.indexOf(close, contentStart);
    const position = positionAt(template, start);

    if (end === -1) {
      throw new TemplateError("Unclosed tag", position);
    }

    const content = template.slice(contentStart, end).trim();
    cursor = end + close.length;

    if (triple) {
      target.push({
        type: "value",
        path: requirePath(content, position, "interpolation"),
        escaped: false,
        position,
      });
      continue;
    }

    if (content.startsWith("!")) {
      continue;
    }

    if (content === "else") {
      const open = stack.at(-1);
      if (!open) {
        throw new TemplateError("else outside a block", position);
      }
      if (open.inElse) {
        throw new TemplateError("Duplicate else", position);
      }
      open.inElse = true;
      target = open.node.alternate;
      continue;
    }

    if (content.startsWith("#")) {
      const match = /^#(\S+)(?:\s+(.+))?$/.exec(content);
      const kind = match?.[1];
      if (kind !== "if" && kind !== "each") {
        throw new TemplateError(`Unknown block ${kind ? `"${kind}"` : "tag"}`, position);
      }
      const path = requirePath(match?.[2]?.trim() ?? "", position, `#${kind}`);
      const node: BlockNode = {
        type: kind,
        path,
        consequent: [],
        alternate: [],
        position,
      };
      target.push(node);
      stack.push({ node, parent: target, inElse: false });
      target = node.consequent;
      continue;
    }

    if (content.startsWith("/")) {
      const kind = content.slice(1).trim();
      const open = stack.at(-1);
      if (!open) {
        throw new TemplateError(`Closing ${kind || "block"} without an open block`, position);
      }
      if (kind !== open.node.type) {
        throw new TemplateError(
          `Mismatched closing block: expected /${open.node.type}, got /${kind || "?"}`,
          position,
        );
      }
      stack.pop();
      target = open.parent;
      continue;
    }

    target.push({
      type: "value",
      path: requirePath(content, position, "interpolation"),
      escaped: true,
      position,
    });
  }

  const unclosed = stack.at(-1);
  if (unclosed) {
    throw new TemplateError(`Unclosed #${unclosed.node.type} block`, unclosed.node.position);
  }

  return root;
}

const MISSING = Symbol("missing");

function lookup(value: unknown, parts: string[]): unknown | typeof MISSING {
  let current = value;

  for (const part of parts) {
    if ((typeof current !== "object" || current === null) && typeof current !== "function") {
      return MISSING;
    }
    if (!Object.prototype.hasOwnProperty.call(current, part)) {
      return MISSING;
    }
    current = (current as Record<string, unknown>)[part];
  }

  return current;
}

function resolve(path: string, context: RenderContext): unknown | typeof MISSING {
  const loop = context.loops.at(-1);

  if (path === "this") return loop ? loop.value : context.root;
  if (path.startsWith("this.")) {
    return lookup(loop ? loop.value : context.root, path.slice(5).split("."));
  }
  if (path === "@index") return loop ? loop.index : MISSING;

  const parts = path.split(".");
  if (parts.some((part) => part.length === 0)) return MISSING;

  if (loop) {
    const local = lookup(loop.value, parts);
    if (local !== MISSING) return local;
  }
  return lookup(context.root, parts);
}

function isTruthy(value: unknown | typeof MISSING): boolean {
  if (value === MISSING || value === null || value === undefined) return false;
  if (Array.isArray(value)) return value.length > 0;
  return value !== "" && value !== 0 && value !== false;
}

function scalarText(value: unknown | typeof MISSING, node: ValueNode): string {
  if (value === MISSING || value === null || value === undefined) return "";
  if (
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "bigint" ||
    typeof value === "boolean"
  ) {
    return String(value);
  }
  throw new TemplateError(
    `Cannot render non-scalar value at path "${node.path}"`,
    node.position,
  );
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case "\"": return "&quot;";
      default: return "&#39;";
    }
  });
}

function renderNodes(nodes: Node[], context: RenderContext): string {
  let output = "";

  for (const node of nodes) {
    if (node.type === "text") {
      output += node.value;
      continue;
    }

    const value = resolve(node.path, context);
    if (node.type === "value") {
      const text = scalarText(value, node);
      output += node.escaped ? escapeHtml(text) : text;
      continue;
    }

    if (node.type === "if") {
      output += renderNodes(isTruthy(value) ? node.consequent : node.alternate, context);
      continue;
    }

    if (Array.isArray(value) && value.length > 0) {
      for (let index = 0; index < value.length; index += 1) {
        output += renderNodes(node.consequent, {
          root: context.root,
          loops: [...context.loops, { value: value[index], index }],
        });
      }
    } else {
      output += renderNodes(node.alternate, context);
    }
  }

  return output;
}

export function render(template: string, data: unknown): string {
  return renderNodes(parse(template), { root: data, loops: [] });
import { render } from "./engine";

async function main(): Promise<void> {
  const [templatePath, dataPath, ...extra] = Bun.argv.slice(2);
  if (!templatePath || !dataPath || extra.length > 0) {
    throw new Error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  }

  const [template, json] = await Promise.all([
    Bun.file(templatePath).text(),
    Bun.file(dataPath).text(),
  ]);
  const data: unknown = JSON.parse(json);
  await Bun.write(Bun.stdout, render(template, data));
}

try {
  await main();
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  console.error(`mini-template: ${message}`);
  process.exitCode = 1;
}
import { describe, expect, test } from "bun:test";
import { render } from "../src/engine";

describe("render", () => {
  test("escapes values and supports raw values and comments", () => {
    expect(render("A {{value}} B {{{value}}}{{! ignored }}", { value: `&<>\"'` }))
      .toBe("A &amp;&lt;&gt;&quot;&#39; B &<>\"'");
  });

  test("renders missing values as empty strings", () => {
    expect(render("x{{missing.deep}}y", {})).toBe("xy");
  });

  test("handles if truthiness, nesting, and else", () => {
    expect(render("{{#if a}}A{{#if b}}B{{else}}C{{/if}}{{else}}D{{/if}}", { a: [], b: true }))
      .toBe("D");
    expect(render("{{#if a}}A{{#if b}}B{{else}}C{{/if}}{{else}}D{{/if}}", { a: [1], b: 0 }))
      .toBe("AC");
  });

  test("iterates nested arrays with item paths, index, and root fallback", () => {
    const template = "{{#each groups}}[{{name}}/{{title}}:{{#each values}}{{@index}}={{this}};{{else}}empty{{/each}}]{{/each}}";
    expect(render(template, {
      title: "root",
      groups: [{ name: "a", values: ["x", "y"] }, { name: "b", values: [] }],
    })).toBe("[a/root:0=x;1=y;][b/root:empty]");
  });

  test("each else handles missing and non-array values", () => {
    expect(render("{{#each items}}x{{else}}none{{/each}}", { items: "no" })).toBe("none");
  });

  test("preserves whitespace exactly", () => {
    expect(render(" \n{{! x }}\t{{value}}\n", { value: "ok" })).toBe(" \n\tok\n");
  });

  test("rejects structural errors with locations", () => {
    expect(() => render("one\n{{else}}", {})).toThrow("else outside a block at line 2, column 1");
    expect(() => render("{{#if x}}{{else}}{{else}}{{/if}}", {})).toThrow("Duplicate else");
    expect(() => render("{{#if x}}{{/each}}", {})).toThrow("expected /if, got /each");
    expect(() => render("{{#wat x}}{{/wat}}", {})).toThrow('Unknown block "wat"');
    expect(() => render("{{#if x}}", {})).toThrow("Unclosed #if block");
  });

  test("rejects non-scalar interpolation", () => {
    expect(() => render("{{user}}", { user: { name: "Ada" } })).toThrow(
      'Cannot render non-scalar value at path "user" at line 1, column 1',
    );
  });
